  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--color-accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius);
  text-decoration: none;
  font-weight: 600;
  z-index: 100;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 1rem;
}

/* Page header */
header {
  text-align: center;
  margin-bottom: 2.5rem;
}

header h1 {
  font-size: clamp(1.6rem, 4vw, 2.25rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text-primary);
}

header p {
  margin-top: 0.5rem;
  color: var(--color-text-secondary);
  font-size: 0.975rem;
}

/* Card */
main {
  width: 100%;
  max-width: 480px;
}

.card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: calc(var(--radius) * 2);
  padding: 2.25rem 2rem;
}

/* Form */
form {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

/* Form field wrapper */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

/* Label row */
.label-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
}

label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-primary);
}

.required-mark {
  color: #f05a6e;
  margin-left: 0.2em;
  aria-hidden: true;
}

.optional-badge {
  font-size: 0.75rem;
  color: var(--color-text-secondary);
  font-weight: 400;
}

