.helper-text {
  font-size: 0.8rem;
  color: var(--color-text-secondary);
}

.error-message {
  font-size: 0.8rem;
  color: var(--color-text-error);
  display: none;
  align-items: center;
  gap: 0.3em;
}

.error-message[aria-hidden="false"],
.error-message:not([aria-hidden]) {
  display: flex;
}

.error-icon {
  flex-shrink: 0;
  width: 14px;
  height: 14px;
  fill: currentColor;
}

/* Submit button */
.btn-submit {
  width: 100%;
  padding: 0.75rem 1.5rem;
  background: var(--color-accent);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition);
  margin-top: 0.5rem;
  outline: none;
}

.btn-submit:hover {
  background: var(--color-accent-hover);
}

.btn-submit:active {
  background: var(--color-accent-active);
}

.btn-submit:focus-visible {
  outline: 2px solid var(--color-border-focus);
  outline-offset: 3px;
  box-shadow: 0 0 0 4px rgba(108, 126, 247, 0.25);
}

/* Success message */
#success-message {
  display: none;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 1rem;
  padding: 1rem 0;
}

#success-message.visible {
  display: flex;
}

.success-icon {
  width: 56px;
  height: 56px;
  fill: var(--color-valid);
}

#success-message h2 {
  font-size: 1.3rem;
  font-weight: 700;
}

#success-message p {
  color: var(--color-text-secondary);
  font-size: 0.95rem;
}

/* Live region */
#form-status {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
