/* Card */
main {
  width: 100%;
  max-width: 480px;
}

.card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: calc(var(--radius) * 2);
  padding: 2.25rem 2rem;
}

/* Form */
form {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

/* Form field wrapper */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

/* Label row */
.label-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
}

label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-primary);
}

.required-mark {
  color: #f05a6e;
  margin-left: 0.2em;
  aria-hidden: true;
}

.optional-badge {
  font-size: 0.75rem;
  color: var(--color-text-secondary);
  font-weight: 400;
}

/* Inputs */
input[type="text"],
input[type="email"],
input[type="tel"] {
  width: 100%;
  padding: 0.65rem 0.875rem;
  background: var(--color-surface-raised);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius);
  color: var(--color-text-primary);
  font-size: 0.975rem;
  font-family: inherit;
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
  min-width: 0;
}

input::placeholder {
  color: var(--color-text-secondary);
  opacity: 0.6;
}

input:focus {
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgba(108, 126, 247, 0.25);
  outline: 2px solid transparent;
}

input[aria-invalid="true"] {
  border-color: var(--color-border-error);
}

input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(240, 90, 110, 0.25);
}

input[aria-invalid="false"]:not(:placeholder-shown) {
  border-color: var(--color-valid);
}

/* Helper and error text */
.helper-text {
  font-size: 0.8rem;
  color: var(--color-text-secondary);
}

.error-message {
  font-size: 0.8rem;
  color: var(--color-text-error);
  display: none;
  align-items: center;
  gap: 0.3em;
}

.error-message[aria-hidden="false"],
.error-message:not([aria-hidden]) {
  display: flex;
}

.error-icon {
  flex-shrink: 0;
  width: 14px;
  height: 14px;
  fill: currentColor;
}

/* Submit button */
.btn-submit {
  width: 100%;
  padding: 0.75rem 1.5rem;
  background: var(--color-accent);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition);
  margin-top: 0.5rem;
  outline: none;
}

.btn-submit:hover {
  background: var(--color-accent-hover);
}

.btn-submit:active {
  background: var(--color-accent-active);
}

.btn-submit:focus-visible {
  outline: 2px solid var(--color-border-focus);
  outline-offset: 3px;
  box-shadow: 0 0 0 4px rgba(108, 126, 247, 0.25);
}

/* Success message */
#success-message {
  display: none;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 1rem;
  padding: 1rem 0;
}

#success-message.visible {
  display: flex;
}

.success-icon {
  width: 56px;
  height: 56px;
  fill: var(--color-valid);
}

#success-message h2 {
  font-size: 1.3rem;
  font-weight: 700;
}

#success-message p {
  color: var(--color-text-secondary);
  font-size: 0.95rem;
}

/* Live region */
#form-status {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* Responsive */
@media (max-width: 520px) {
  .card {
    padding: 1.5rem 1.25rem;
  }
}

@media (forced-colors: active) {
  input:focus,
  .btn-submit:focus-visible {
    outline: 2px solid ButtonText;
  }
  .btn-submit {
    background: ButtonFace;
    color: ButtonText;
    border: 1px solid ButtonBorder;
  }
}
