  const successMsg = document.getElementById("success-message");
  const formStatus = document.getElementById("form-status");

  const RULES = {
    fullName: {
      required: true,
      validate(val) {
        if (!val) return "Full name is required.";
        if (val.trim().length < 2) return "Please enter your full name (at least 2 characters).";
        return null;
      },
    },
    email: {
      required: true,
      validate(val) {
        if (!val) return "Email address is required.";
        // RFC-5322 simplified pattern
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(val)) {
          return "Enter a valid email address (e.g., name@example.com).";
        }
        return null;
      },
    },
    phone: {
      required: false,
      validate(val) {
        if (!val) return null; // optional
        // Allow common formats: digits, spaces, dashes, dots, parens, leading +
        if (!/^\+?[\d\s\-().]{7,20}$/.test(val)) {
          return "Enter a valid phone number (e.g., +1 800 555 0100).";
        }
        return null;
      },
    },
  };

  function getField(name) {
    return {
      input: document.getElementById(name),
      error: document.getElementById(`${name}-error`),
    };
  }

  function showError(name, message) {
    const { input, error } = getField(name);
    input.setAttribute("aria-invalid", "true");
    error.textContent = message;
    error.setAttribute("aria-hidden", "false");
    error.style.display = "flex";
  }

  function clearError(name) {
    const { input, error } = getField(name);
    input.setAttribute("aria-invalid", "false");
    error.textContent = "";
    error.setAttribute("aria-hidden", "true");
    error.style.display = "none";
  }

  function validateField(name) {
    const { input } = getField(name);
    const val = input.value.trim();
    const error = RULES[name].validate(val);
    if (error) {
      showError(name, error);
      return false;
    }
    clearError(name);
    return true;
  }

  // Validate on blur for each field
  Object.keys(RULES).forEach((name) => {
    const { input } = getField(name);
    input.addEventListener("blur", () => {
      // Only validate on blur if the field was interacted with
      if (input.value.trim() || RULES[name].required) {
        validateField(name);
      }
    });

    input.addEventListener("input", () => {
      // Clear error as the user types if there was one
      if (input.getAttribute("aria-invalid") === "true") {
        validateField(name);
      }
    });
