    e.preventDefault();

    const results = Object.keys(RULES).map((name) => validateField(name));
    const allValid = results.every(Boolean);

    if (!allValid) {
      // Focus the first invalid field
      const firstInvalid = Object.keys(RULES).find(
        (name) => getField(name).input.getAttribute("aria-invalid") === "true"
      );
      if (firstInvalid) {
        getField(firstInvalid).input.focus();
      }
