+}
+
+header p {
+  margin-top: 0.5rem;
+  color: var(--color-text-secondary);
+  font-size: 0.975rem;
+}
+
+/* Card */
+main {
+  width: 100%;
+  max-width: 480px;
+}
+
+.card {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: calc(var(--radius) * 2);
+  padding: 2.25rem 2rem;
+}
+
+/* Form */
+form {
+  display: flex;
+  flex-direction: column;
+  gap: 1.5rem;
+}
+
+/* Form field wrapper */
+.form-field {
+  display: flex;
+  flex-direction: column;
+  gap: 0.35rem;
+}
+
+/* Label row */
+.label-row {
+  display: flex;
+  align-items: baseline;
+  justify-content: space-between;
+  gap: 0.5rem;
+}
+
+label {
+  font-size: 0.875rem;
+  font-weight: 600;
+  color: var(--color-text-primary);
+}
+
+.required-mark {
+  color: #f05a6e;
+  margin-left: 0.2em;
+  aria-hidden: true;
+}
+
+.optional-badge {
+  font-size: 0.75rem;
+  color: var(--color-text-secondary);
+  font-weight: 400;
+}
+
+/* Inputs */
+input[type="text"],
+input[type="email"],
+input[type="tel"] {
+  width: 100%;
+  padding: 0.65rem 0.875rem;
+  background: var(--color-surface-raised);
+  border: 1.5px solid var(--color-border);
+  border-radius: var(--radius);
+  color: var(--color-text-primary);
+  font-size: 0.975rem;
+  font-family: inherit;
+  transition: border-color var(--transition), box-shadow var(--transition);
+  outline: none;
+  min-width: 0;
+}
+
+input::placeholder {
+  color: var(--color-text-secondary);
+  opacity: 0.6;
+}
+
+input:focus {
+  border-color: var(--color-border-focus);
+  box-shadow: 0 0 0 3px rgba(108, 126, 247, 0.25);
+  outline: 2px solid transparent;
+}
+
+input[aria-invalid="true"] {
+  border-color: var(--color-border-error);
+}
+
+input[aria-invalid="true"]:focus {
+  box-shadow: 0 0 0 3px rgba(240, 90, 110, 0.25);
+}
+
+input[aria-invalid="false"]:not(:placeholder-shown) {
+  border-color: var(--color-valid);
+}
+
+/* Helper and error text */
+.helper-text {
+  font-size: 0.8rem;
+  color: var(--color-text-secondary);
+}
+
+.error-message {
+  font-size: 0.8rem;
+  color: var(--color-text-error);
+  display: none;
+  align-items: center;
+  gap: 0.3em;
+}
+
+.error-message[aria-hidden="false"],
